// Prove the second run did not duplicate or delete anything.
const before = $('Fetch Qdrant Vectors Pre-Sync').first().json?.result?.points_count ?? 0;
const after  = $('Fetch Qdrant Vectors Post-Sync').first().json?.result?.points_count ?? 0;
const run = $('Post Dataset to Qdrant').first().json?.data ?? {};
if (run.status && run.status !== 'SUCCEEDED') {
  return [{ json: { sync_run: run.id, sync_status: run.status,
    verdict: `Sync still ${run.status} when the report ran. Counts below are not final.` } }];
}
const raw  = $('Retrieve Sync Log').first().json;
const text = typeof raw === 'string' ? raw : (raw?.data ?? JSON.stringify(raw));
const m = String(text).match(/to add: (\d+), to update last_seen_at: (\d+), to delete: (\d+)/);
const added = m ? +m[1] : null;
const refreshed = m ? +m[2] : null;
const deleted = m ? +m[3] : null;
let verdict;
if (m === null)              verdict = 'Could not read the sync log. Check the Actor run.';
else if (added || deleted)   verdict = `${added} chunks added, ${deleted} removed, ${refreshed} unchanged.`;
else                         verdict = `Nothing changed. ${refreshed} chunks kept, zero re-embedded.`;
return [{ json: {
  crawl_run:  $('When Apify Job Completes').first().json.resource.id,
  dataset:    $('When Apify Job Completes').first().json.resource.defaultDatasetId,
  vectors_before: before,
  vectors_after:  after,
  chunks_added: added, chunks_refreshed: refreshed, chunks_deleted: deleted,
  verdict
} }];
